#!/usr/bin/env python3
import csv, gzip, io, json, re, sys
from collections import defaultdict
from datetime import datetime, timedelta, timezone, date
from decimal import Decimal, ROUND_HALF_UP
from fractions import Fraction
from pathlib import Path
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    b = Path(path).read_bytes()
    if b[:2] == b'\x1f\x8b':
        b = gzip.decompress(b)
    return b.decode('utf-8-sig')


def lines_of(text):
    for ln in text.split('\n'):
        ln = ln.rstrip('\r')
        if ln.strip() != '':
            yield ln


def epoch(dt):
    return int(dt.astimezone(UTC).timestamp()) if dt.tzinfo else None


def local_to_epoch(naive, tz, dst=None):
    """naive local datetime -> epoch seconds. dst: None (first occurrence) or bool for repeated times."""
    a = naive.replace(tzinfo=tz, fold=0)
    b = naive.replace(tzinfo=tz, fold=1)
    if a.utcoffset() != b.utcoffset() and dst is not None:
        # ambiguous (or gap); choose by dst flag
        cands = [x for x in (a, b) if bool(x.dst()) == dst]
        if cands:
            return int(cands[0].timestamp())
    return int(a.timestamp())


def std_offset(tz, year=2026):
    best = None
    for m in range(1, 13):
        d = datetime(year, m, 15, 12, tzinfo=tz)
        if not d.dst():
            return d.utcoffset()
        best = d.utcoffset() if best is None else min(best, d.utcoffset())
    return best


# ---- format parsers: yield (id, emp, dir, epoch) ----

def parse_abbr(text, tz):
    header = None
    for row in csv.reader(io.StringIO(text)):
        if not row or all(c.strip() == '' for c in row):
            continue
        cells = [c.strip() for c in row]
        if 'Badge' in cells and 'Punch' in cells:
            header = {n: i for i, n in enumerate(cells)}
            continue
        if header is None:
            continue
        g = lambda n: cells[header[n]]
        m = re.fullmatch(r'(\d+):(\d+):(\d+)\s*([AaPp][Mm])?', g('Time'))
        h, mi, s = int(m.group(1)), int(m.group(2)), int(m.group(3))
        ap = m.group(4)
        if ap:
            ap = ap.upper()
            h = h % 12 + (12 if ap == 'PM' else 0)
        mo, d, y = map(int, g('Date').split('/'))
        naive = datetime(y, mo, d, h, mi, s)
        z = g('Zone').upper()
        dst = z.endswith('DT')
        yield g('Record'), g('Badge'), g('Punch').upper(), local_to_epoch(naive, tz, dst)


