            else:
                off = std
        elif t == 'D':
            pid = ln[1:9]
            badge = ln[9:15].strip()
            d = 'IN' if ln[15] == 'I' else 'OUT'
            dt = datetime.strptime(ln[16:30], '%Y%m%d%H%M%S')
            yield pid, 'E' + badge, d, int((dt - timedelta(seconds=off.total_seconds())).replace(tzinfo=UTC).timestamp())


