            continue
        naive = datetime.strptime(row['local_time'], '%Y-%m-%d %H:%M:%S')
        yield row['punch_ref'], row['employee_id'], row['direction'].upper(), local_to_epoch(naive, tz)


def parse_local_jsonl(text, tz):
