    pstart = date.fromisoformat(period['start'])
    pend = date.fromisoformat(period['end'])
    cutoff = parse_ts(period['corrections_cutoff'])
    sites = {r['site']: ZoneInfo(r['timezone']) for r in read_csv(inp / 'sites.csv')}
    site_fmt = {r['site']: r['format'] for r in read_csv(inp / 'sites.csv')}
    employees = read_csv(inp / 'employees.csv')
    emp_home = {e['employee_id']: e['home_site'] for e in employees}
    rates = defaultdict(list)
    for r in read_csv(inp / 'rates.csv'):
        rates[r['employee_id']].append((date.fromisoformat(r['effective_from']), Decimal(r['hourly_rate'])))
    for v in rates.values():
