        if b <= a:
            return 0
        oa = datetime.fromtimestamp(a, tz).utcoffset()
        ob = datetime.fromtimestamp(b, tz).utcoffset()
        if oa == ob:
            la = a + int(oa.total_seconds()); lb = b + int(ob.total_seconds())
            total = 0
            day0 = la // 86400 - 1
            day1 = lb // 86400 + 1
            for dday in range(day0, day1 + 1):
                base = dday * 86400
                for ws, we in ((0, 6 * 3600), (22 * 3600, 24 * 3600)):
                    lo = max(la, base + ws); hi = min(lb, base + we)
                    if hi > lo:
                        total += hi - lo
            return total // 60
        n = 0
        for t in range(a, b, 60):
            h = datetime.fromtimestamp(t, tz).hour
            if h >= 22 or h < 6:
                n += 1
        return n

    for emp, lst in by_emp.items():
        home = sites[emp_home[emp]]
        lst.sort()
        kept = []
        last = None
        for t, o, site, pid, dr in lst:
            if last is not None and last[4] == dr and t - last[0] <= 300:
                if in_period(workday(rnd(t, sites[site]), home)):
                    exc['duplicates_dropped'] += 1
                continue
            last = (t, o, site, pid, dr)
            kept.append((rnd(t, sites[site]), dr, site))
        shifts = []
        i = 0
        n = len(kept)
        while i < n:
            rt, dr, site = kept[i]
            if dr == 'IN':
                if i + 1 < n and kept[i + 1][1] == 'OUT' and kept[i + 1][0] - rt <= 16 * 3600:
                    shifts.append((rt, kept[i + 1][0], site))
                    i += 2
                    continue
                if in_period(workday(rt, home)):
                    exc['open_shifts'] += 1
            else:
                if in_period(workday(rt, home)):
                    exc['orphan_outs'] += 1
            i += 1
        shifts = [s for s in shifts if in_period(workday(s[0], home))]
        shifts.sort(key=lambda s: s[0])
        daily_used = defaultdict(int)
        week_used = defaultdict(int)
        r = res[emp]
        for a, b, site in shifts:
            wd = workday(a, home)
            worked = max(0, (b - a) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(a, b, sites[site]), paid)
            before = daily_used[wd]
            daily_used[wd] += paid
            dot = max(0, before + paid - 480) - max(0, before - 480)
            normal = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = week_used[wk]
            week_used[wk] += normal
            wot = max(0, wb + normal - 2400) - max(0, wb - 2400)
            ot = dot + wot
            reg = paid - ot
            rate = None
            for ef, rv in rates[emp]:
                if ef <= wd:
                    rate = rv
            if rate is None:
                rate = rates[emp][0][1] if rates[emp] else Decimal(0)
            rf = Fraction(rate)
            pay = rf * (reg + Fraction(3, 2) * ot) / 60 + rf * Fraction(15, 100) * night / 60
            r['shifts'] += 1
            r['paid_minutes'] += paid
            r['overtime_minutes'] += ot
            r['night_minutes'] += night
            r['gross'] += pay

    def money(fr):
        return (fr * 100 + Fraction(1, 2)).__floor__()

    out_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totg = 0
    for e in sorted(res):
        r = res[e]
        c = money(r['gross'])
        totg += c
        for k in tot:
            tot[k] += r[k]
        out_emps[e] = {k: r[k] for k in tot}
        out_emps[e]['gross'] = '%d.%02d' % divmod(c, 100)
    tot['gross'] = '%d.%02d' % divmod(totg, 100)
    exc['corrections_applied'] = applied
    outp.parent.mkdir(parents=True, exist_ok=True)
    outp.write_text(json.dumps({'period': {'start': period['start'], 'end': period['end']},
                                'employees': out_emps, 'exceptions': exc, 'totals': tot}, indent=1))


